/**
 * Definition for binary tree
 * class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) {
 *         val = x;
 *         left = null;
 *         right = null;
 *     }
 * }
 */
public class Solution {
    public int lca(TreeNode A, int B, int C) {
        if (!exists(A, B) || !exists(A, C)) {
            return -1;
        }
        TreeNode ans = helper(A, B, C);
        return ans == null ? -1 : ans.val;
    }

    private TreeNode helper(TreeNode node, int B, int C) {
        if (node == null) return null;
        if (node.val == B || node.val == C) return node;
        TreeNode left = helper(node.left, B, C);
        TreeNode right = helper(node.right, B, C);
        if (left != null && right != null) return node;
        return left != null ? left : right;
    }

    private boolean exists(TreeNode node, int val) {
        if (node == null) return false;
        if (node.val == val) return true;
        return exists(node.left, val) || exists(node.right, val);
    }
}

/**
 * Definition for binary tree
 * class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) {
 *         val = x;
 *         left = null;
 *         right = null;
 *     }
 * }
 */
public class Solution {
    public int hasPathSum(TreeNode A, int B) {
        return dfs(A, B) ? 1 : 0;
    }

    private boolean dfs(TreeNode node, int sum) {
        if (node == null) return false;
        sum -= node.val;
        if (node.left == null && node.right == null) {
            return sum == 0;
        }
        return dfs(node.left, sum) || dfs(node.right, sum);
    }
}

/**
 * Definition for binary tree
 * class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) {
 *         val = x;
 *         left = null;
 *         right = null;
 *     }
 * }
 */
public class Solution {
    private int count = 0;
    private int ans = -1;

    public int kthsmallest(TreeNode A, int B) {
        count = 0;
        ans = -1;
        inorder(A, B);
        return ans;
    }

    private void inorder(TreeNode node, int B) {
        if (node == null || ans != -1) return;
        inorder(node.left, B);
        count++;
        if (count == B) {
            ans = node.val;
            return;
        }
        inorder(node.right, B);
    }
}

/**
 * Definition for binary tree
 * class TreeNode {
 *     int val;
 *     TreeNode left;
 *     TreeNode right;
 *     TreeNode(int x) {
 *         val = x;
 *         left = null;
 *         right = null;
 *     }
 * }
 */
public class Solution {
    public int solve(TreeNode A, int B, int C) {
        TreeNode node = A;
        while (node != null) {
            if (B < node.val && C < node.val) {
                node = node.left;
            } else if (B > node.val && C > node.val) {
                node = node.right;
            } else {
                return node.val;
            }
        }
        return -1;
    }
}

