public class Solution {
    public int[] solve(TreeNode A) {
        List<Integer> res = new ArrayList<>();
        TreeNode cur = A;
        while (cur != null) {
            if (cur.left == null) {
                res.add(cur.val);
                cur = cur.right;
            } else {
                TreeNode pred = cur.left;
                while (pred.right != null && pred.right != cur) {
                    pred = pred.right;
                }
                if (pred.right == null) {
                    pred.right = cur;
                    cur = cur.left;
                } else {
                    pred.right = null;
                    res.add(cur.val);
                    cur = cur.right;
                }
            }
        }
        int[] ans = new int[res.size()];
        for (int i = 0; i < res.size(); i++) ans[i] = res.get(i);
        return ans;
    }
}

public class Solution {
    private TreeNode first, second, prev;
    public int[] recoverTree(TreeNode A) {
        first = second = prev = null;
        inorder(A);
        int a = first.val, b = second.val;
        if (a < b) { int t = a; a = b; b = t; }   // examples show larger value first
        return new int[]{a, b};
    }
    private void inorder(TreeNode node) {
        if (node == null) return;
        inorder(node.left);
        if (prev != null && prev.val > node.val) {
            if (first == null) first = prev;
            second = node;
        }
        prev = node;
        inorder(node.right);
    }
}

public class Solution {
    static final int MOD = 1000000007;
    public int solve(TreeNode A, TreeNode B) {
        List<Integer> a = new ArrayList<>();
        List<Integer> b = new ArrayList<>();
        inorder(A, a);
        inorder(B, b);
        int i = 0, j = 0;
        long sum = 0;
        while (i < a.size() && j < b.size()) {
            int x = a.get(i), y = b.get(j);
            if (x == y) {
                sum = (sum + x) % MOD;
                i++; j++;
            } else if (x < y) {
                i++;
            } else {
                j++;
            }
        }
        return (int) sum;
    }
    private void inorder(TreeNode node, List<Integer> out) {
        if (node == null) return;
        inorder(node.left, out);
        out.add(node.val);
        inorder(node.right, out);
    }
}

public class Solution {
    public int solve(TreeNode A, int B, int C) {
        TreeNode lca = A;
        while (lca != null) {
            if (B < lca.val && C < lca.val) lca = lca.left;
            else if (B > lca.val && C > lca.val) lca = lca.right;
            else break;
        }
        return dist(lca, B) + dist(lca, C);
    }
    private int dist(TreeNode node, int key) {
        int d = 0;
        while (node != null && node.val != key) {
            if (key < node.val) node = node.left;
            else node = node.right;
            d++;
        }
        return d;
    }
}

public class Solution {
    public TreeLinkNode connect(TreeLinkNode A) {
        if (A == null) return null;
        TreeLinkNode leftmost = A;
        while (leftmost.left != null) {
            TreeLinkNode head = leftmost;
            while (head != null) {
                head.left.next = head.right;
                if (head.next != null) {
                    head.right.next = head.next.left;
                }
                head = head.next;
            }
            leftmost = leftmost.left;
        }
        return A;
    }
}

