public class Solution {
    public int[][] verticalOrderTraversal(TreeNode A) {
        if (A == null) return new int[0][0];
        TreeMap<Integer, List<Integer>> map = new TreeMap<>();
        Queue<TreeNode> nodes = new LinkedList<>();
        Queue<Integer> hds = new LinkedList<>();
        nodes.add(A);
        hds.add(0);
        while (!nodes.isEmpty()) {
            TreeNode node = nodes.poll();
            int hd = hds.poll();
            map.computeIfAbsent(hd, k -> new ArrayList<>()).add(node.val);
            if (node.left != null) { nodes.add(node.left); hds.add(hd - 1); }
            if (node.right != null) { nodes.add(node.right); hds.add(hd + 1); }
        }
        int[][] res = new int[map.size()][];
        int i = 0;
        for (List<Integer> col : map.values()) {
            int[] row = new int[col.size()];
            for (int j = 0; j < col.size(); j++) row[j] = col.get(j);
            res[i++] = row;
        }
        return res;
    }
}

