public class Solution {
    public int[] solve(TreeNode A) {
        if (A == null) return new int[0];
        TreeMap<Integer, Integer> map = new TreeMap<>();
        Queue<TreeNode> nodes = new LinkedList<>();
        Queue<Integer> hds = new LinkedList<>();
        nodes.add(A);
        hds.add(0);
        while (!nodes.isEmpty()) {
            TreeNode node = nodes.poll();
            int hd = hds.poll();
            if (!map.containsKey(hd)) map.put(hd, node.val);
            if (node.left != null) { nodes.add(node.left); hds.add(hd - 1); }
            if (node.right != null) { nodes.add(node.right); hds.add(hd + 1); }
        }
        int[] res = new int[map.size()];
        int i = 0;
        for (int v : map.values()) res[i++] = v;
        return res;
    }
}

public class Solution {
    private int best = 0;
    public int solve(TreeNode A) {
        best = 0;
        height(A);
        return best;
    }
    private int height(TreeNode node) {
        if (node == null) return -1;
        int l = height(node.left);
        int r = height(node.right);
        best = Math.max(best, l + r + 2);
        return 1 + Math.max(l, r);
    }
}

public class Solution {
    public int isSameTree(TreeNode A, TreeNode B) {
        return same(A, B) ? 1 : 0;
    }
    private boolean same(TreeNode A, TreeNode B) {
        if (A == null && B == null) return true;
        if (A == null || B == null) return false;
        if (A.val != B.val) return false;
        return same(A.left, B.left) && same(A.right, B.right);
    }
}

public class Solution {
    public TreeNode invertTree(TreeNode A) {
        if (A == null) return null;
        TreeNode temp = A.left;
        A.left = A.right;
        A.right = temp;
        invertTree(A.left);
        invertTree(A.right);
        return A;
    }
}
